def _font_size(key):
    return int(key.rsplit("-", 1)[1])


def _decode_fonts():
    """Expand the packed glyph bitmaps into per-pixel 0..3 values."""
    out = {}
    for key, glyphs in FONTS.items():
        dec = {}
        for ch, g in glyphs.items():
            xoff, yoff, w, h, adv, b64 = g
            if w == 0 or h == 0 or not b64:
                dec[ch] = (xoff, yoff, w, h, adv, b"")
                continue
            raw = base64.b64decode(b64)
            vals = bytearray(w * h)
            for i in range(w * h):
                vals[i] = (raw[i >> 1] >> (4 if i % 2 == 0 else 0)) & 15
            dec[ch] = (xoff, yoff, w, h, adv, bytes(vals))
        out[key] = dec
    return out


_GLYPHS = _decode_fonts()

SERIF_B = lambda s: "DejaVuSerif-Bold-%d" % s
SERIF = lambda s: "DejaVuSerif-%d" % s
SERIF_I = lambda s: "Default-%d" % s
SANS = lambda s: "DejaVuSans-%d" % s
SANS_B = lambda s: "DejaVuSans-Bold-%d" % s
MONO_B = lambda s: "DejaVuSansMono-Bold-%d" % s


def text_length(key, text):
    glyphs = _GLYPHS[key]
    total = 0
    for ch in text:
        g = glyphs.get(ch)
        total += g[4] if g else 0
    return total


def _draw_text(put, x, y, text, key, color):
    """Draw text with the embedded bitmap font.

    put(x, y, color, alpha) plots one pixel; (x, y) is the anchor
    (top-left, ascender) exactly like Pillow's default text anchor.
    """
    glyphs = _GLYPHS[key]
    cx = x
    for ch in text:
        g = glyphs.get(ch)
        if g is None:
            continue
        xoff, yoff, w, h, adv, vals = g
        if w and h:
            for py in range(h):
                row = py * w
                for px in range(w):
                    v = vals[row + px]
                    if v:
                        put(cx + xoff + px, y + yoff + py, color, v * 17)
        cx += adv


# --- Canvas (RGB, alpha-aware drawing) -----------------------------------

class Canvas(object):
    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.px = bytearray(w * h * 3)
        r, g, b = bg
        for i in range(w * h):
            self.px[3 * i] = r
            self.px[3 * i + 1] = g
            self.px[3 * i + 2] = b

    def blend(self, x, y, color, alpha):
        if alpha <= 0 or not (0 <= x < self.w and 0 <= y < self.h):
            return
        i = (y * self.w + x) * 3
        if alpha >= 255:
            self.px[i], self.px[i + 1], self.px[i + 2] = color
        else:
            ia = 255 - alpha
            self.px[i] = (color[0] * alpha + self.px[i] * ia) // 255
            self.px[i + 1] = (color[1] * alpha + self.px[i + 1] * ia) // 255
            self.px[i + 2] = (color[2] * alpha + self.px[i + 2] * ia) // 255

    def put(self, x, y, color, alpha):
        self.blend(x, y, color, alpha)

    def fill_rect(self, x0, y0, x1, y1, color, alpha=255):
        x0 = max(0, x0)
        y0 = max(0, y0)
        x1 = min(self.w - 1, x1)
        y1 = min(self.h - 1, y1)
        for yy in range(y0, y1 + 1):
            base = yy * self.w
            for xx in range(x0, x1 + 1):
                self.blend(xx, yy, color, alpha)

    def rect_outline(self, x0, y0, x1, y1, color, width=1, alpha=255):
        for t in range(width):
            self.fill_rect(x0 + t, y0 + t, x1 - t, y0 + t, color, alpha)
            self.fill_rect(x0 + t, y1 - t, x1 - t, y1 - t, color, alpha)
            self.fill_rect(x0 + t, y0 + t, x0 + t, y1 - t, color, alpha)
            self.fill_rect(x1 - t, y0 + t, x1 - t, y1 - t, color, alpha)

    def _brush(self, x, y, color, width, alpha):
        r = width // 2
        for yy in range(y - r, y - r + width):
            for xx in range(x - r, x - r + width):
                self.blend(xx, yy, color, alpha)

    def line(self, x0, y0, x1, y1, color, width=1, alpha=255):
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        x, y = x0, y0
        while True:
            self._brush(x, y, color, width, alpha)
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x += sx
            if e2 <= dx:
                err += dx
                y += sy

    def ellipse_fill(self, x0, y0, x1, y1, color, alpha=255):
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        if rx <= 0 or ry <= 0:
            return
        for yy in range(y0, y1 + 1):
            d = (yy - cy) / ry
            if abs(d) > 1:
                continue
            dx = rx * math.sqrt(max(0.0, 1.0 - d * d))
            xa = int(math.ceil(cx - dx))
            xb = int(math.floor(cx + dx))
            for xx in range(xa, xb + 1):
                self.blend(xx, yy, color, alpha)

    def ellipse_outline(self, x0, y0, x1, y1, color, width=1, alpha=255):
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        if rx <= 0 or ry <= 0:
            return
        n = max(24, int(2 * math.pi * max(rx, ry)) + 8)
        for k in range(n):
            a = 2 * math.pi * k / n
            self._brush(int(round(cx + rx * math.cos(a))),
                        int(round(cy + ry * math.sin(a))),
                        color, width, alpha)

    def polygon_fill(self, pts, color, alpha=255):
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        for yy in range(min(ys), max(ys) + 1):
            xs = []
            n = len(pts)
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if y0 == y1:
                    continue
                lo, hi = (y0, y1) if y0 < y1 else (y1, y0)
                if lo <= yy < hi:
                    xs.append(x0 + (yy + 0.5 - y0) * (x1 - x0) / (y1 - y0))
            xs.sort()
            for j in range(0, len(xs) - 1, 2):
                xa = int(math.ceil(xs[j]))
                xb = int(math.floor(xs[j + 1]))
                for xx in range(xa, xb + 1):
                    self.blend(xx, yy, color, alpha)

    def arc(self, x0, y0, x1, y1, start, end, color, width=1, alpha=255):
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        sweep = (end - start) % 360
        if sweep == 0:
            sweep = 360
        steps = max(8, int(sweep) + 1)
        for k in range(steps + 1):
            a = math.radians(start + sweep * k / steps)
            self._brush(int(round(cx + rx * math.cos(a))),
                        int(round(cy + ry * math.sin(a))),
                        color, width, alpha)

    def pieslice(self, x0, y0, x1, y1, start, end, color, alpha=255):
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        rx = (x1 - x0) / 2.0
        ry = (y1 - y0) / 2.0
        if rx <= 0 or ry <= 0:
            return
        sweep = (end - start) % 360
        if sweep == 0:
            sweep = 360
        for yy in range(y0, y1 + 1):
            for xx in range(x0, x1 + 1):
                ddx = (xx - cx) / rx
                ddy = (yy - cy) / ry
                if ddx * ddx + ddy * ddy > 1.0:
                    continue
                ang = math.degrees(math.atan2(yy - cy, xx - cx)) % 360
                if (ang - start) % 360 <= sweep:
                    self.blend(xx, yy, color, alpha)

    def rounded_rect_outline(self, x0, y0, x1, y1, radius, color,
                             width=1, alpha=255):
        r = radius
        self.line(x0 + r, y0, x1 - r, y0, color, width, alpha)
        self.line(x0 + r, y1, x1 - r, y1, color, width, alpha)
        self.line(x0, y0 + r, x0, y1 - r, color, width, alpha)
        self.line(x1, y0 + r, x1, y1 - r, color, width, alpha)
        self.arc(x0, y0, x0 + 2 * r, y0 + 2 * r, 180, 270, color, width,
                 alpha)
        self.arc(x1 - 2 * r, y0, x1, y0 + 2 * r, 270, 360, color, width,
                 alpha)
        self.arc(x1 - 2 * r, y1 - 2 * r, x1, y1, 0, 90, color, width, alpha)
        self.arc(x0, y1 - 2 * r, x0 + 2 * r, y1, 90, 180, color, width,
                 alpha)

    def text(self, x, y, s, key, color, alpha=255):
        if alpha >= 255:
            _draw_text(self.put, x, y, s, key, color)
        else:
            _draw_text(lambda xx, yy, c, a: self.blend(xx, yy, c, a * alpha // 255),
                       x, y, s, key, color)


# --- RGBA layer (for the rotated visa stamps) ----------------------------

class Layer(object):
    def __init__(self, w, h):
        self.w = w
        self.h = h
        self.px = bytearray(w * h * 4)

    def put(self, x, y, color, alpha):
        if alpha <= 0 or not (0 <= x < self.w and 0 <= y < self.h):
            return
        i = (y * self.w + x) * 4
        self.px[i], self.px[i + 1], self.px[i + 2] = color
        self.px[i + 3] = max(self.px[i + 3], alpha)

    def rounded_rect_outline(self, x0, y0, x1, y1, radius, color, width=1):
        tmp = Canvas(self.w, self.h, (0, 0, 0))
        tmp.rounded_rect_outline(x0, y0, x1, y1, radius, color, width)
        for yy in range(self.h):
            for xx in range(self.w):
                i = (yy * self.w + xx) * 3
                if tmp.px[i] or tmp.px[i + 1] or tmp.px[i + 2]:
                    self.put(xx, yy, color, 255)

    def text(self, x, y, s, key, color):
        _draw_text(self.put, x, y, s, key, color)

    def rotate(self, angle_deg):
        out = Layer(self.w, self.h)
        cx = (self.w - 1) / 2.0
        cy = (self.h - 1) / 2.0
        a = math.radians(angle_deg)
        ca, sa = math.cos(a), math.sin(a)
        for dy in range(self.h):
            for dx in range(self.w):
                rx = dx - cx
                ry = dy - cy
                sx = int(round(cx + rx * ca - ry * sa))
                sy = int(round(cy + rx * sa + ry * ca))
                if 0 <= sx < self.w and 0 <= sy < self.h:
                    si = (sy * self.w + sx) * 4
                    if self.px[si + 3]:
                        di = (dy * self.w + dx) * 4
                        out.px[di:di + 4] = self.px[si:si + 4]
        return out

    def composite_onto(self, canvas, ox, oy):
        for yy in range(self.h):
            for xx in range(self.w):
                i = (yy * self.w + xx) * 4
                a = self.px[i + 3]
                if a:
                    canvas.blend(xx + ox, yy + oy,
                                 (self.px[i], self.px[i + 1], self.px[i + 2]),
                                 a)


# --- PNG writer (stdlib only) --------------------------------------------

def write_png(canvas, path):
    raw = bytearray()
    w, h = canvas.w, canvas.h
    for y in range(h):
        raw.append(0)
        raw += canvas.px[y * w * 3:(y + 1) * w * 3]
    comp = zlib.compress(bytes(raw), 6)

    def chunk(typ, data):
        out = struct.pack(">I", len(data)) + typ + data
        out += struct.pack(">I", zlib.crc32(typ + data) & 0xFFFFFFFF)
        return out

    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    with open(path, "wb") as f:
        f.write(b"\x89PNG\r\n\x1a\n")
        f.write(chunk(b"IHDR", ihdr))
        f.write(chunk(b"IDAT", comp))
        f.write(chunk(b"IEND", b""))


def spaced(text):
    """Letter-spaced capitals, as on real passport headings."""
    return " ".join(text)


def text_center(cv, cx, y, text, fnt, fill):
    w = text_length(fnt, text)
    cv.text(int(cx - w / 2), y, text, fnt, fill)


def text_left(cv, x, y, text, fnt, fill):
    cv.text(x, y, text, fnt, fill)


# --- Machine-readable zone (ICAO TD3 check digits) -----------------------

def _mrz_value(ch):
    if ch == "<":
        return 0
    if ch.isdigit():
        return int(ch)
    return ord(ch) - ord("A") + 10


def mrz_check(text):
    weights = (7, 3, 1)
    total = 0
    for i, ch in enumerate(text):
        total += _mrz_value(ch) * weights[i % 3]
    return str(total % 10)


def mrz_lines():
    line1 = "P<VLDLINDQVIST<<ELIN<SOFIA"
    line1 = line1 + "<" * (44 - len(line1))
    doc = "VL0729451"
    dob = "900904"      # 04 SEP 1990
    expiry = "320117"   # 17 JAN 2032
    body = (
        doc + mrz_check(doc)
        + "VLD"
        + dob + mrz_check(dob)
        + "F"
        + expiry + mrz_check(expiry)
        + "<" * 14
    )
    line2 = body + mrz_check(body)
    return line1, line2


# --- Portrait (drawn, not a photo) ---------------------------------------

def draw_portrait(cv, x0, y0, x1, y1):
    """Stylised portrait of a woman with tied-back hair, green sweater."""
    cv.fill_rect(x0, y0, x1, y1, (174, 195, 212))
    cv.rect_outline(x0, y0, x1, y1, INK, 2)
    cx = (x0 + x1) // 2
    # shoulders / sweater
    cv.pieslice(cx - 62, y1 - 78, cx + 62, y1 + 30, 180, 360, (47, 88, 76))
    cv.fill_rect(cx - 62, y1 - 40, cx + 62, y1, (47, 88, 76))
    # collar
    cv.polygon_fill([(cx - 16, y1 - 40), (cx + 16, y1 - 40), (cx, y1 - 18)],
                    (240, 236, 222))
    # neck
    cv.fill_rect(cx - 11, y1 - 96, cx + 11, y1 - 72, (232, 192, 152))
    # hair behind head + bun
    cv.ellipse_fill(cx - 40, y0 + 18, cx + 40, y0 + 96, (125, 90, 60))
    cv.ellipse_fill(cx - 16, y0 + 2, cx + 16, y0 + 30, (125, 90, 60))
    # head
    cv.ellipse_fill(cx - 33, y0 + 30, cx + 33, y0 + 112, (236, 195, 156))
    # hair framing the face
    cv.pieslice(cx - 33, y0 + 28, cx + 33, y0 + 92, 180, 360, (125, 90, 60))
    cv.ellipse_fill(cx - 38, y0 + 52, cx - 24, y0 + 104, (125, 90, 60))
    cv.ellipse_fill(cx + 24, y0 + 52, cx + 38, y0 + 104, (125, 90, 60))
    # brows, eyes, nose, smile
    cv.line(cx - 20, y0 + 66, cx - 8, y0 + 64, (90, 60, 35), 2)
    cv.line(cx + 8, y0 + 64, cx + 20, y0 + 66, (90, 60, 35), 2)
    cv.ellipse_fill(cx - 18, y0 + 70, cx - 12, y0 + 76, (40, 40, 40))
    cv.ellipse_fill(cx + 12, y0 + 70, cx + 18, y0 + 76, (40, 40, 40))
    cv.line(cx, y0 + 74, cx - 2, y0 + 88, (200, 150, 110), 2)
    cv.arc(cx - 10, y0 + 90, cx + 10, y0 + 104, 15, 165, (150, 80, 60), 2)


# --- Visa stamps ----------------------------------------------------------

def draw_stamp(base, cx, cy, angle, color, lines):
    """One rotated rectangular border stamp, centred at (cx, cy).

    Drawn on an oversized transparent layer so rotation never clips
    the stamp's corners.
    """
    w, h = 268, 118
    pad = 46
    layer = Layer(w + 2 * pad, h + 2 * pad)
    x0, y0, x1, y1 = pad + 4, pad + 4, pad + w - 5, pad + h - 5
    layer.rounded_rect_outline(x0, y0, x1, y1, 10, color, 3)
    layer.rounded_rect_outline(x0 + 6, y0 + 6, x1 - 6, y1 - 6, 7, color, 1)
    y = y0 + 10
    for text, fnt in lines:
        tw = text_length(fnt, text)
        layer.text(int((w + 2 * pad - tw) / 2), y, text, fnt, color)
        y += int(_font_size(fnt) * 1.3) + 2
    layer = layer.rotate(angle)
    layer.composite_onto(base, int(cx - w / 2 - pad),
                         int(cy - h / 2 - pad))


def stamp_lines(country, kind, place, date):
    return [
        (country, SANS_B(16)),
        (kind, SANS_B(12)),
        (place, SERIF(14)),
        (date, SANS_B(15)),
    ]


# --- Spread layout -------------------------------------------------------

def draw_background(cv):
    """Cream paper with a faint guilloche of interlocking circles.

    Note: the original drew these shapes with an alpha channel on an
    RGBA canvas and converted to RGB at the end, which in Pillow drops
    the alpha instead of compositing it -- so the circles, border and
    spine render as solid colours. We draw them solid to match.
    """
    for gx in range(0, W, 46):
        for gy in range(0, H, 46):
            cv.ellipse_outline(gx - 16, gy - 16, gx + 16, gy + 16,
                               (190, 175, 140), 1)
    # outer border
    cv.rect_outline(6, 6, W - 7, H - 7, (90, 80, 60), 2)
    # centre spine: one soft fold line, not a solid bar
    cv.line(W // 2 - 2, 8, W // 2 - 2, H - 9, (120, 100, 70), 1)
    cv.line(W // 2, 8, W // 2, H - 9, (110, 95, 70), 1)
    cv.line(W // 2 + 2, 8, W // 2 + 2, H - 9, (120, 100, 70), 1)


def draw_emblem(cv, cx, cy):
    """Circular state emblem: a lighthouse over waves."""
    r = 34
    cv.ellipse_outline(cx - r, cy - r, cx + r, cy + r, INK, 3)
    cv.ellipse_outline(cx - r + 6, cy - r + 6, cx + r - 6, cy + r - 6,
                       INK, 1)
    # lighthouse tower
    cv.polygon_fill([(cx - 5, cy + 16), (cx - 3, cy - 14),
                     (cx + 3, cy - 14), (cx + 5, cy + 16)], INK)
    cv.fill_rect(cx - 7, cy - 20, cx + 7, cy - 14, INK)
    cv.polygon_fill([(cx - 8, cy - 20), (cx, cy - 28), (cx + 8, cy - 20)],
                    INK)
    # light beams
    cv.line(cx - 8, cy - 17, cx - 26, cy - 24, INK, 2)
    cv.line(cx + 8, cy - 17, cx + 26, cy - 24, INK, 2)
    # waves
    for yy in (cy + 20, cy + 26):
        cv.arc(cx - 20, yy - 6, cx - 2, yy + 6, 180, 360, INK, 2)
        cv.arc(cx + 2, yy - 6, cx + 20, yy + 6, 180, 360, INK, 2)


def field(cv, x, y, label, value, value_font=None, label_width=None):
    text_left(cv, x, y, label, SANS(10), INK_SOFT)
    text_left(cv, x, y + 14, value,
              value_font or SERIF_B(17), INK)


def rule(cv, x0, x1, y):
    cv.line(x0, y, x1, y, RULE, 1)


def build_spread():
    cv = Canvas(W, H, PAPER)
    draw_background(cv)

    # ---- left page: visas --------------------------------------------
    lx, rx = 22, 496
    text_center(cv, (lx + rx) // 2, 26, spaced("VISUM · VISAS"),
                SERIF_B(24), INK)
    text_center(cv, (lx + rx) // 2, 58,
                "INNREISE- OG UTREISESTEMPEL · ENTRY AND EXIT STAMPS",
                SANS(10), INK_SOFT)
    rule(cv, lx + 10, rx - 10, 80)

    draw_stamp(cv, 165, 165, -6, STAMP_BLUE, stamp_lines(
        "KINGDOM OF OSTERMARK", "INNREISE · ENTRY", "Varna Harbour",
        "08 JUN 2023"))
    draw_stamp(cv, 350, 300, 5, STAMP_BLUE, stamp_lines(
        "KINGDOM OF OSTERMARK", "UTREISE · EXIT", "Varna Harbour",
        "15 JUN 2023"))
    draw_stamp(cv, 165, 435, -4, STAMP_RED, stamp_lines(
        "REPUBLIC OF CALDORIA", "ANKOMST · ENTRY", "Mirell Ferry Port",
        "19 OCT 2024"))
    draw_stamp(cv, 350, 570, 6, STAMP_RED, stamp_lines(
        "REPUBLIC OF CALDORIA", "AVREISE · EXIT", "Mirell Ferry Port",
        "26 OCT 2024"))
    text_left(cv, 30, 684, "8", SANS(11), INK_SOFT)

    # ---- right page: data --------------------------------------------
    px, qx = 534, 1002
    draw_emblem(cv, 574, 62)
    text_left(cv, 622, 34, "REPUBLIK VALDORIA", SERIF_B(28), INK)
    text_left(cv, 624, 66, spaced("REPUBLIC OF VALDORIA"),
              SANS(11), INK_SOFT)
    rule(cv, px, qx, 96)
    text_center(cv, (px + qx) // 2, 104, spaced("PASS · PASSPORT"),
                SERIF_B(15), INK)
    rule(cv, px, qx, 130)

    # top row: type / code / number
    field(cv, px + 6, 142, "TYP · TYPE", "P")
    field(cv, 660, 142, "LANDKODE · CODE", "VLD")
    field(cv, 830, 142, "PASSNR · PASSPORT", "VL 0729451")
    rule(cv, px, qx, 186)

    # portrait + fields beside it
    draw_portrait(cv, px + 6, 198, px + 156, 198 + 185)
    field(cv, 712, 198, "ETTERNAMN · SURNAME", "LINDQVIST")
    rule(cv, 712, qx, 234)
    field(cv, 712, 244, "FORNAVN · GIVEN NAMES", "ELIN SOFIA")
    rule(cv, 712, qx, 280)
    field(cv, 712, 290, "STATSBORGERSKAP · NATIONALITY", "VALDORIAN")
    rule(cv, 712, qx, 326)
    field(cv, 712, 336, "FØDT · DATE OF BIRTH", "04 SEP 1990")
    field(cv, 920, 336, "KJØNN · SEX", "F")
    rule(cv, px, qx, 388)

    # signature under the portrait
    text_left(cv, px + 6, 396, "Elin Lindqvist", SERIF_I(20), INK)
    text_left(cv, px + 6, 424, "UNDERSKRIFT · SIGNATURE",
              SANS(9), INK_SOFT)

    # lower rows, full width
    field(cv, 712, 396, "FØDESTED · PLACE OF BIRTH", "ALDVIK")
    rule(cv, px, qx, 448)
    field(cv, px + 6, 458, "UTSTEDT · ISSUED", "17 JAN 2022")
    field(cv, 712, 458, "GYLDIG TIL · EXPIRES", "17 JAN 2032")
    rule(cv, px, qx, 494)
    field(cv, px + 6, 504, "UTSTEDENDE MYNDIGHET · AUTHORITY",
          "PASSPORT OFFICE · ALDVIK")
    rule(cv, px, qx, 540)
    text_left(cv, px + 6, 550, "MERKNAD · OBSERVATION",
              SANS(10), INK_SOFT)
    text_left(cv, px + 6, 566,
              "The holder may cross the northern border on foot",
              SERIF_I(13), INK)
    text_left(cv, px + 6, 584,
              "without a visa during the light season.",
              SERIF_I(13), INK)

    # machine-readable zone
    line1, line2 = mrz_lines()
    cv.fill_rect(px, 612, qx, 668, MRZ_BG)
    text_left(cv, px + 8, 620, line1, MONO_B(15), INK)
    text_left(cv, px + 8, 642, line2, MONO_B(15), INK)

    return cv


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    write_png(build_spread(), path)
    print("wrote", path)


if __name__ == "__main__":
    main()
